def _A_v(y):
    """A number for a table cell: negatives as math, so the minus stays on the left."""
    return f'${y:g}$' if y < 0 else f'{y:g}'


def OPTPAIR(code, title_he, story, side, typ, prem, who, why, connect, payrule, pnlq, pnlwhy, pnlrule, ends):
    """Two slides per position. First the payoff, built price by price in a table beside the chart.
    Then the profit: the same three prices less (or plus) the premium, the rule, and the three key numbers."""
    K = 100
    f = (lambda s: max(s - K, 0)) if typ == 'call' else (lambda s: max(K - s, 0))
    pay = [(x, side * f(x)) for x in (70, 100, 130)]
    pr = [(x, y - side * prem) for x, y in pay]
    L = 'c' if typ == 'call' else 'p'
    Y, XT, YT = (-40, 40), [70, 80, 90, 100, 110, 120, 130], [-40, -20, 0, 20, 40]
    col = '#0f9d90' if side > 0 else '#ff6a4d'
    marks = [dict(x=x, y=y, t=f'{y:g}'.replace('-', '−'), dy=(-12 if y >= 0 else 22), s=3 + i, c=PAYC) for i, (x, y) in enumerate(pay)]
    rows = []
    for i, ((x, y), w) in enumerate(zip(pay, why)):
        how = ('$' + (f'{x} − {K}' if typ == 'call' else f'{K} − {x}') + '$') if y > 0 else (('$' + (f'{K} − {x}' if typ == 'call' else f'{x} − {K}') + '$') if y < 0 else '')
        rows.append([f'<b>{x}</b>', w, _A_cell(_A_v(y), how)])
    S(f's-{code}1', f'{title_he}: התזרים', f'{title_he}: התזרים בפקיעה (Payoff)',
      f'<div class="card qstem op-q"><p>{TX(story)}</p></div>'
      + STEPS(CHART([dict(pts=pay, c=PAYC, s=6)], 70, 130, *Y, XT, YT, H=420, xl='מחיר המניה בפקיעה, S_T', yl='תזרים (Payoff)', xs=1, ys=2, marks=marks),
              RL(['<b>ציר אופקי:</b> מחיר המניה בפקיעה, $S_{T}$.', '<b>ציר אנכי:</b> התזרים (Payoff), עדיין בלי הפרמיה. הקו הכהה הוא אפס.'])
              + TABLES(['$S_{T}$', 'מה קורה במחיר הזה', 'תזרים (Payoff)'], rows, 'op-t', 3)
              + RL([(6, f'<b>מחברים את הנקודות:</b> {connect}')])
              + ST(7, TX(payrule), cls='op-r')), kick=f'חלק {CUR[0]} · בנייה בהדרגה')
    marks2 = [dict(x=x, y=y, t=f'{y:g}'.replace('-', '−'), dy=(-12 if y >= 0 else 22), s=2 + i, c=col) for i, (x, y) in enumerate(pr)]
    be = K + prem if typ == 'call' else K - prem
    marks2.append(dict(x=be, y=0, t=f'{be:g}', dx=(14 if typ == 'call' else -14), dy=(22 if side > 0 else -12), s=6, c='#16213a'))
    sg = '−' if side > 0 else '+'
    rows2 = []
    for (x, y), (_, z) in zip(pay, pr):
        rows2.append([f'<b>{x}</b>', _A_v(y), f'${sg}{prem}$', f'<b class="gv">{_A_v(z)}</b> <span class="gi">' + f'(${y:g} {sg} {prem}$)'.replace('-', '−') + '</span>'])
    S(f's-{code}2', f'{title_he}: הרווח', f'{title_he}: הרווח או ההפסד (P&L)',
      f'<div class="card qstem op-q"><p>{TX(pnlq)}</p></div>'
      + STEPS(CHART([dict(pts=pay, c='#c9c4d9', w=3), dict(pts=pr, c=col, s=5)], 70, 130, *Y, XT, YT, H=410, xl='מחיר המניה בפקיעה, S_T', yl='רווח או הפסד (P&L)', marks=marks2),
              RL([pnlwhy])
              + TABLES(['$S_{T}$', 'תזרים (Payoff)', ('פחות' if side > 0 else 'ועוד') + f' הפרמיה, ${L}$', 'רווח או הפסד (P&L)'], rows2, 'op-t', 2)
              + ST(5, TX(pnlrule), cls='op-r')
              + TABLES(['המספר', 'ערך', 'איך ולמה'], ends, 'op-e', 6)), kick=f'חלק {CUR[0]} · בנייה בהדרגה')


